package app.relaydrop;

import android.content.*;
import android.net.Uri;
import android.provider.DocumentsContract;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.charset.CodingErrorAction;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Portable content backup. Device credentials and Android Keystore keys are intentionally absent. */
final class PoolBackup {
  static final AtomicBoolean BUSY=new AtomicBoolean();
  static final int MAX_MANIFEST=16*1024*1024;
  static final long MAX_FILE=20L*1024*1024*1024;
  static String strictUtf8(byte[] bytes)throws IOException {return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();}
  interface Progress {void update(String message);void check()throws IOException;}
  static String hash(byte[] data)throws Exception{return ShareTransport.hex(MessageDigest.getInstance("SHA-256").digest(data));}
  static byte[] read(InputStream source,int limit)throws IOException {if(source==null)throw new IOException("无法读取备份文件。");try(InputStream in=source;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[65536];for(int n;(n=in.read(b))!=-1;){if(out.size()+n>limit)throw new IOException("备份清单超过限制。");out.write(b,0,n);}return out.toByteArray();}}
  static String safeName(String name){String n=java.text.Normalizer.normalize(name,java.text.Normalizer.Form.NFC).replaceAll("[\\x00-\\x1f\\x7f/\\\\:*?\"<>|]","_").trim().replaceAll("[. ]+$","");if(n.isEmpty()||n.equals(".")||n.equals(".."))n="文件";if(n.matches("(?i)(CON|PRN|AUX|NUL|COM[1-9¹²³]|LPT[1-9¹²³])(\\..*)?"))n="_"+n;if(n.length()>110)n=n.substring(0,Character.isHighSurrogate(n.charAt(109))?109:110);return n;}
  static String payloadPath(String path)throws IOException {if(path==null||path.length()>2048||!path.startsWith("files/")||path.indexOf('\\')>=0)throw new IOException("备份路径无效。");String[] parts=path.split("/",-1);if(parts.length>40)throw new IOException("备份路径过深。");for(String p:parts){if(!SafTreeFiles.wellFormed(p)||!java.text.Normalizer.isNormalized(p,java.text.Normalizer.Form.NFC)||p.length()>255||p.isEmpty()||!p.equals(p.trim())||p.equals(".")||p.equals("..")||p.endsWith(".")||p.matches("(?s).*[\\x00-\\x1f\\x7f/:*?\"<>|].*")||p.matches("(?i)(CON|PRN|AUX|NUL|COM[1-9¹²³]|LPT[1-9¹²³])(\\..*)?"))throw new IOException("备份路径含有不安全名称。");}return path;}
  private static Uri resolve(ContentResolver resolver,Uri tree,String path)throws IOException {payloadPath(path);Uri uri=SafTreeFiles.root(tree);for(String part:path.split("/")){uri=SafTreeFiles.find(resolver,tree,uri,part);if(uri==null)throw new IOException("备份文件缺失："+path);}return uri;}
  private static String unique(String candidate,Set<String> used){String value=candidate;int count=1;while(!used.add(value.toLowerCase(Locale.ROOT))){int slash=candidate.lastIndexOf('/'),dot=candidate.lastIndexOf('.');if(dot<=slash)dot=candidate.length();value=candidate.substring(0,dot)+" ("+(++count)+")"+candidate.substring(dot);}return value;}
  static JSONObject manifest(JSONObject snapshot,String serverId)throws Exception {
    JSONArray folders=new JSONArray(),files=new JSONArray(),notes=new JSONArray();JSONArray all=snapshot.getJSONArray("folders");for(int i=0;i<all.length();i++){JSONObject f=all.getJSONObject(i);folders.put(new JSONObject().put("id",f.getString("id")).put("parentId",f.opt("parentId")).put("name",f.getString("name")));}
    Set<String> used=new HashSet<>();used.add("files");used.add("files/共享文件");used.add("files/定向文件");used.add("files/回收站");for(int i=0;i<folders.length();i++)used.add(("files/共享文件/"+String.join("/",SharedFolders.path(snapshot,folders.getJSONObject(i).getString("id")))).toLowerCase(Locale.ROOT));all=snapshot.getJSONArray("files");if(all.length()>50000)throw new IOException("备份文件清单超过 50,000 项。");for(int i=0;i<all.length();i++){JSONObject f=all.getJSONObject(i);boolean shared=f.isNull("targetId")||f.optString("targetId").isEmpty(),trash=f.has("deletedAt");String folder=shared&&!f.isNull("folderId")?f.optString("folderId"):null,base=trash?"files/回收站/"+f.getString("id"):!shared?"files/定向文件/"+f.getString("id"):"files/共享文件";if(shared&&!trash&&folder!=null)base+="/"+String.join("/",SharedFolders.path(snapshot,folder));String path=unique(base+"/"+safeName(f.getString("name")),used);payloadPath(path);files.put(new JSONObject().put("id",f.getString("id")).put("path",path).put("name",f.getString("name")).put("folderId",folder==null?JSONObject.NULL:folder).put("size",f.getLong("size")).put("sha256",f.getString("sha256")).put("mime",f.optString("mime","application/octet-stream")).put("createdAt",f.optString("createdAt")).put("lastModified",f.optLong("lastModified")).put("visibility",shared?"shared":"private").put("deletedAt",trash?f.getString("deletedAt"):JSONObject.NULL));}
    all=snapshot.getJSONArray("notes");if(all.length()>50000)throw new IOException("备份文字清单超过限制。");for(int i=0;i<all.length();i++){JSONObject n=all.getJSONObject(i);notes.put(new JSONObject().put("id",n.getString("id")).put("text",n.getString("text")).put("createdAt",n.optString("createdAt")).put("visibility",n.isNull("targetId")||n.optString("targetId").isEmpty()?"shared":"private"));}
    return new JSONObject().put("format","relaydrop-pool-backup").put("version",1).put("createdAt",new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",Locale.US){{setTimeZone(TimeZone.getTimeZone("UTC"));}}.format(new Date())).put("source",new JSONObject().put("name",android.os.Build.MODEL).put("serverId",serverId==null?JSONObject.NULL:serverId)).put("folders",folders).put("files",files).put("notes",notes);
  }
  static void validate(JSONObject manifest)throws Exception {
    if(!"relaydrop-pool-backup".equals(manifest.optString("format"))||!(manifest.opt("version") instanceof Number)||manifest.getDouble("version")!=1||!date(manifest.opt("createdAt"))||manifest.optJSONObject("source")==null||!(manifest.getJSONObject("source").opt("name") instanceof String)||manifest.getJSONObject("source").getString("name").length()>256)throw new IOException("不是支持的文件池备份。");JSONArray folders=manifest.getJSONArray("folders"),files=manifest.getJSONArray("files"),notes=manifest.getJSONArray("notes");if(folders.length()>5000||files.length()>50000||notes.length()>50000)throw new IOException("备份项目数量超过限制。");JSONObject tree=new JSONObject().put("folders",folders);SharedFolders.validateTree(tree);Set<String> ids=new HashSet<>(),paths=new HashSet<>();
    for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String id=SharedFolders.nullable(f,"id"),path=payloadPath(f.getString("path"));if(id==null||!ids.add(id)||!paths.add(path.toLowerCase(Locale.ROOT)))throw new IOException("备份文件编号或路径重复。");Object raw=f.opt("size");if(!(raw instanceof Number)||((Number)raw).doubleValue()!=((Number)raw).longValue()||f.getLong("size")<0||f.getLong("size")>MAX_FILE||!f.getString("sha256").matches("[a-f0-9]{64}"))throw new IOException("备份大小或哈希无效。");String name=f.getString("name");if(name.length()<1||name.length()>255||name.matches("(?s).*[\\x00-\\x1f\\x7f/\\\\].*")||name.equals(".")||name.equals(".."))throw new IOException("备份原文件名无效。");String visibility=f.getString("visibility");if(!visibility.equals("shared")&&!visibility.equals("private"))throw new IOException("备份接收范围无效。");String folder=SharedFolders.nullable(f,"folderId");SharedFolders.find(tree,folder);if(visibility.equals("private")&&folder!=null)throw new IOException("定向文件不能属于共享目录。");if(!f.isNull("deletedAt")&&!f.getString("deletedAt").matches("[0-9]{4}-[0-9]{2}-[0-9]{2}T.*Z"))throw new IOException("回收站时间无效。");}
    for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String name=f.getString("name");Object modified=f.opt("lastModified");if(!SafTreeFiles.wellFormed(name)||name.trim().isEmpty()||!date(f.opt("createdAt"))||!(modified instanceof Number)||((Number)modified).doubleValue()!=((Number)modified).longValue()||((Number)modified).longValue()<0||((Number)modified).longValue()>9007199254740991L||!(f.opt("mime") instanceof String)||f.getString("mime").length()>200||!f.isNull("deletedAt")&&!date(f.opt("deletedAt")))throw new IOException("备份文件名称、日期或类型无效。");}
    for(String path:paths){String[] pieces=path.split("/");String parent="";for(int i=0;i<pieces.length-1;i++){parent=parent.isEmpty()?pieces[i]:parent+"/"+pieces[i];if(paths.contains(parent))throw new IOException("备份文件与目录路径冲突。");}}
    for(int i=0;i<notes.length();i++){JSONObject n=notes.getJSONObject(i);String id=SharedFolders.nullable(n,"id"),text=n.getString("text"),visibility=n.getString("visibility");if(id==null||!ids.add(id)||!(n.opt("text") instanceof String)||text.length()>20000||text.trim().isEmpty()||text.indexOf('\0')>=0||!date(n.opt("createdAt"))||(!visibility.equals("shared")&&!visibility.equals("private")))throw new IOException("备份文字无效。");}
  }
  private static boolean date(Object value){if(!(value instanceof String)||((String)value).length()>40)return false;try{java.time.Instant.parse((String)value);return true;}catch(Exception invalid){return false;}}
  private static void directory(ContentResolver resolver,Uri tree,Uri root,String path,Map<String,Uri> known)throws IOException {String prefix="";Uri parent=root;for(String part:path.split("/")){String next=prefix.isEmpty()?part:prefix+"/"+part;Uri child=known.get(next);if(child==null){child=SafTreeFiles.create(resolver,tree,parent,part,true);known.put(next,child);}parent=child;prefix=next;}}
  private static String copy(InputStream in,OutputStream out,long size,Progress progress)throws Exception {MessageDigest digest=MessageDigest.getInstance("SHA-256");byte[] block=new byte[65536];long count=0;for(int n;(n=in.read(block))!=-1;){progress.check();count+=n;if(count>size)throw new IOException("文件长度超过备份记录。");if(out!=null)out.write(block,0,n);digest.update(block,0,n);}if(count!=size)throw new IOException("文件长度与备份记录不一致。");if(out!=null)out.flush();return ShareTransport.hex(digest.digest());}
  static Uri export(Context context,RelayHttpServer server,Uri destination,Progress progress)throws Exception {
    NativeStorageGate.beginMaintenance();if(!BUSY.compareAndSet(false,true)){NativeStorageGate.endMaintenance();throw new IOException("已有文件池存储任务正在运行。");}boolean locked=false;try{JSONObject snapshot=server.beginStorageOperation();locked=true;JSONObject manifest=manifest(snapshot,server.identity()==null?null:server.identity().serverId);validate(manifest);ContentResolver resolver=context.getContentResolver();String label="星月夜备份-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date())+"-"+UUID.randomUUID().toString().substring(0,6);Uri root=SafTreeFiles.create(resolver,destination,SafTreeFiles.root(destination),label,true);Map<String,Uri> directories=new HashMap<>();directories.put("",root);JSONArray files=manifest.getJSONArray("files");
      directory(resolver,destination,root,"files/共享文件",directories);JSONArray folders=manifest.getJSONArray("folders");for(int i=0;i<folders.length();i++){progress.check();directory(resolver,destination,root,"files/共享文件/"+String.join("/",SharedFolders.path(snapshot,folders.getJSONObject(i).getString("id"))),directories);}
      for(int i=0;i<files.length();i++){progress.check();JSONObject f=files.getJSONObject(i);String path=f.getString("path");progress.update("备份并读回校验 "+(i+1)+" / "+files.length()+"："+f.getString("name"));String parentPath=path.substring(0,path.lastIndexOf('/'));directory(resolver,destination,root,parentPath,directories);Uri output=SafTreeFiles.create(resolver,destination,directories.get(parentPath),path.substring(path.lastIndexOf('/')+1),false);try(InputStream in=new FileInputStream(server.backupOriginal(f.getString("id")));OutputStream out=resolver.openOutputStream(output,"w")){if(out==null||!copy(in,out,f.getLong("size"),progress).equals(f.getString("sha256")))throw new IOException("原件校验失败，备份未完成。");}try(InputStream in=resolver.openInputStream(output)){if(in==null||!copy(in,null,f.getLong("size"),progress).equals(f.getString("sha256")))throw new IOException("备份读回校验失败。");}}
      byte[] encoded=manifest.toString(2).getBytes(StandardCharsets.UTF_8);if(encoded.length>MAX_MANIFEST)throw new IOException("备份清单超过 16 MiB。");for(String name:new String[]{"manifest.json","manifest.sha256"}){byte[] data=name.endsWith("json")?encoded:(hash(encoded)+"\n").getBytes(StandardCharsets.US_ASCII);Uri output=SafTreeFiles.create(resolver,destination,root,name,false);try(OutputStream out=resolver.openOutputStream(output,"w")){if(out==null)throw new IOException("无法写入备份清单。");out.write(data);out.flush();}if(!Arrays.equals(data,read(resolver.openInputStream(output),MAX_MANIFEST)))throw new IOException("备份清单读回校验失败。");}return root;
    }finally{if(locked)server.endStorageOperation();BUSY.set(false);NativeStorageGate.endMaintenance();}
  }
  static JSONObject restore(Context context,RelayHttpServer server,Uri tree,Progress progress)throws Exception {
    if(encrypted(context,tree))throw new IOException("该备份已加密，请输入密码后恢复。");
    NativeStorageGate.beginMaintenance();if(!BUSY.compareAndSet(false,true)){NativeStorageGate.endMaintenance();throw new IOException("已有文件池存储任务正在运行。");}File staged=new File(context.getFilesDir(),"pool-restore-"+UUID.randomUUID());boolean locked=false;try{server.beginStorageOperation();locked=true;ContentResolver resolver=context.getContentResolver();Uri root=SafTreeFiles.root(tree),json=SafTreeFiles.find(resolver,tree,root,"manifest.json"),sum=SafTreeFiles.find(resolver,tree,root,"manifest.sha256");if(json==null||sum==null)throw new IOException("请选择包含 manifest.json 和 manifest.sha256 的完整备份目录。");byte[] raw=read(resolver.openInputStream(json),MAX_MANIFEST);String expected=new String(read(resolver.openInputStream(sum),128),StandardCharsets.US_ASCII).trim();if(!expected.matches("[a-f0-9]{64}")||!expected.equals(hash(raw)))throw new IOException("备份清单完整性校验失败。");JSONObject manifest=new JSONObject(strictUtf8(raw));validate(manifest);JSONArray files=manifest.getJSONArray("files");long total=0;for(int i=0;i<files.length();i++){long size=files.getJSONObject(i).getLong("size");if(total>Long.MAX_VALUE-size)throw new IOException("备份总大小无效。");total+=size;}if(total>context.getFilesDir().getUsableSpace()-32L*1024*1024)throw new IOException("手机空间不足以完整暂存并验证备份。");if(!staged.mkdir())throw new IOException("无法创建恢复暂存目录。");
      for(int i=0;i<files.length();i++){progress.check();JSONObject f=files.getJSONObject(i);progress.update("核验备份 "+(i+1)+" / "+files.length()+"："+f.getString("name"));File output=new File(staged,f.getString("id"));try(InputStream in=resolver.openInputStream(resolve(resolver,tree,f.getString("path")));FileOutputStream out=new FileOutputStream(output)){if(in==null||!copy(in,out,f.getLong("size"),progress).equals(f.getString("sha256")))throw new IOException("备份文件校验失败，当前文件池未改变。");out.getFD().sync();}try(InputStream in=new FileInputStream(output)){if(!copy(in,null,f.getLong("size"),progress).equals(f.getString("sha256")))throw new IOException("恢复暂存读回校验失败。");}}
      progress.check();progress.update("全部原件已校验，正在提交恢复…");return server.importVerifiedBackup(manifest,staged);
    }finally{if(locked)server.endStorageOperation();File[] files=staged.listFiles();if(files!=null)for(File f:files)if(f.isFile()&&f.getName().matches("[a-fA-F0-9-]{36}"))f.delete();staged.delete();BUSY.set(false);NativeStorageGate.endMaintenance();}
  }

  static boolean encrypted(Context context,Uri tree)throws IOException{return SafTreeFiles.find(context.getContentResolver(),tree,SafTreeFiles.root(tree),"encrypted-backup.json")!=null;}
  private static Uri child(ContentResolver resolver,Uri tree,String name)throws IOException{Uri value=SafTreeFiles.find(resolver,tree,SafTreeFiles.root(tree),name);if(value==null)throw new IOException("加密备份不完整："+name);return value;}
  static Uri export(Context context,RelayHttpServer server,Uri destination,char[] password,Progress progress)throws Exception {
    if(password==null)return export(context,server,destination,progress);
    NativeStorageGate.beginMaintenance();if(!BUSY.compareAndSet(false,true)){NativeStorageGate.endMaintenance();throw new IOException("已有文件池存储任务正在运行。");}boolean locked=false;byte[] encoded=null;
    try(EncryptedBackup.Context crypto=EncryptedBackup.create(password,progress)){
      JSONObject snapshot=server.beginStorageOperation();locked=true;JSONObject manifest=manifest(snapshot,server.identity()==null?null:server.identity().serverId);validate(manifest);encoded=manifest.toString(2).getBytes(StandardCharsets.UTF_8);if(encoded.length>MAX_MANIFEST)throw new IOException("备份清单超过 16 MiB。");
      ContentResolver resolver=context.getContentResolver();String label="星月夜加密备份-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date())+"-"+UUID.randomUUID().toString().substring(0,6);Uri root=SafTreeFiles.create(resolver,destination,SafTreeFiles.root(destination),label,true),payloads=SafTreeFiles.create(resolver,destination,root,"files",true);JSONArray files=manifest.getJSONArray("files");
      for(int i=0;i<files.length();i++){progress.check();JSONObject f=files.getJSONObject(i);progress.update("加密并读回校验 "+(i+1)+" / "+files.length()+"："+f.getString("name"));String entry="file:"+f.getString("id");Uri output=SafTreeFiles.create(resolver,destination,payloads,f.getString("id")+".rdenc",false);try(InputStream in=new FileInputStream(server.backupOriginal(f.getString("id")));OutputStream out=resolver.openOutputStream(output,"w")){if(out==null)throw new IOException("无法写入加密原件。");EncryptedBackup.encrypt(in,out,crypto,entry,f.getLong("size"),f.getString("sha256"),progress);out.flush();}try(InputStream in=resolver.openInputStream(output)){EncryptedBackup.decrypt(in,null,crypto,entry,f.getLong("size"),f.getString("sha256"),progress);}}
      progress.check();Uri manifestUri=SafTreeFiles.create(resolver,destination,root,"manifest.rdenc",false);String sha=hash(encoded);try(InputStream in=new ByteArrayInputStream(encoded);OutputStream out=resolver.openOutputStream(manifestUri,"w")){if(out==null)throw new IOException("无法写入加密清单。");EncryptedBackup.encrypt(in,out,crypto,"manifest",encoded.length,sha,progress);out.flush();}try(InputStream in=resolver.openInputStream(manifestUri)){EncryptedBackup.decrypt(in,null,crypto,"manifest",encoded.length,sha,progress);}
      progress.check();Uri header=SafTreeFiles.create(resolver,destination,root,"encrypted-backup.json",false);try(OutputStream out=resolver.openOutputStream(header,"w")){if(out==null)throw new IOException("无法写入加密备份头。");out.write(crypto.headerBytes);out.flush();}if(!Arrays.equals(crypto.headerBytes,read(resolver.openInputStream(header),4096)))throw new IOException("备份头读回校验失败。");return root;
    }finally{if(encoded!=null)Arrays.fill(encoded,(byte)0);if(locked)server.endStorageOperation();BUSY.set(false);NativeStorageGate.endMaintenance();}
  }
  static JSONObject restore(Context context,RelayHttpServer server,Uri tree,char[] password,Progress progress)throws Exception {
    if(password==null)return restore(context,server,tree,progress);
    NativeStorageGate.beginMaintenance();if(!BUSY.compareAndSet(false,true)){NativeStorageGate.endMaintenance();throw new IOException("已有文件池存储任务正在运行。");}boolean locked=false;byte[] raw=null;
    try{ContentResolver resolver=context.getContentResolver();Uri header=child(resolver,tree,"encrypted-backup.json");byte[] headerBytes=read(resolver.openInputStream(header),4096);
      try(EncryptedBackup.Context crypto=EncryptedBackup.open(headerBytes,password,progress)){
        server.beginStorageOperation();locked=true;ByteArrayOutputStream decoded=new ByteArrayOutputStream();try(InputStream in=resolver.openInputStream(child(resolver,tree,"manifest.rdenc"))){EncryptedBackup.decrypt(in,decoded,crypto,"manifest",-1,null,progress);}raw=decoded.toByteArray();JSONObject manifest=new JSONObject(strictUtf8(raw));validate(manifest);JSONArray files=manifest.getJSONArray("files");long total=0;
        for(int i=0;i<files.length();i++){long size=files.getJSONObject(i).getLong("size");if(total>Long.MAX_VALUE-size)throw new IOException("备份总大小无效。");total+=size;}if(total>context.getFilesDir().getUsableSpace()-32L*1024*1024)throw new IOException("手机空间不足以恢复完整文件池。");
        for(int i=0;i<files.length();i++){progress.check();JSONObject f=files.getJSONObject(i);progress.update("验证加密备份 "+(i+1)+" / "+files.length()+"："+f.getString("name"));try(InputStream in=resolver.openInputStream(resolve(resolver,tree,"files/"+f.getString("id")+".rdenc"))){EncryptedBackup.decrypt(in,null,crypto,"file:"+f.getString("id"),f.getLong("size"),f.getString("sha256"),progress);}}
        progress.check();progress.update("所有密文和原件已核验，正在恢复…");return server.importVerifiedBackup(manifest,(f,output)->{progress.check();try(InputStream in=resolver.openInputStream(resolve(resolver,tree,"files/"+f.getString("id")+".rdenc"));FileOutputStream out=new FileOutputStream(output)){EncryptedBackup.decrypt(in,out,crypto,"file:"+f.getString("id"),f.getLong("size"),f.getString("sha256"),progress);out.getFD().sync();}try(InputStream in=new FileInputStream(output)){if(!copy(in,null,f.getLong("size"),progress).equals(f.getString("sha256")))throw new IOException("恢复原件读回校验失败。");}});
      }
    }finally{if(raw!=null)Arrays.fill(raw,(byte)0);if(locked)server.endStorageOperation();BUSY.set(false);NativeStorageGate.endMaintenance();}
  }
}
